package main
import (
 "fmt"; "path/filepath"; "time"; "encoding/binary"; "math"; "reflect"
 "mdt-server/internal/protocol"; "mdt-server/internal/vanilla"; "mdt-server/internal/world"; "mdt-server/internal/worldstream"
)
func dump(label string, m *world.WorldModel){fmt.Println(label); for _,p:=range [][2]int{{323,248},{331,248},{339,248},{347,248}}{t,_:=m.TileAt(p[0],p[1]); fmt.Printf("%d,%d block=%s rot=%d",p[0],p[1],m.BlockNames[int16(t.Block)],t.Rotation); if t.Build!=nil{fmt.Printf(" buildRot=%d center=(%d,%d) tail=%x",t.Build.Rotation,t.Build.X,t.Build.Y,t.Build.MapSyncTail); if len(t.Build.MapSyncTail)>=8{fmt.Printf(" reload=%.3f headRot=%.3f", math.Float32frombits(binary.BigEndian.Uint32(t.Build.MapSyncTail[:4])), math.Float32frombits(binary.BigEndian.Uint32(t.Build.MapSyncTail[4:8])))} }; fmt.Println()}}
func inspectIndex(w *world.World, label string){v:=reflect.ValueOf(w).Elem(); idx:=v.FieldByName("turretTilePositions"); states:=v.FieldByName("buildStates"); width:=w.Model().Width; fmt.Println(label, "width", width, "turretIndexLen", idx.Len(), "buildStatesLen", states.Len()); for _,p:=range [][2]int{{323,248},{331,248},{339,248},{347,248}}{pos:=int64(p[1]*width+p[0]); found:=false; for i:=0;i<idx.Len();i++{if idx.Index(i).Int()==pos{found=true; break}}; st:=states.MapIndex(reflect.ValueOf(int32(pos))); fmt.Printf(" pos=%d,%d packed=%d index=%v stateValid=%v",p[0],p[1],pos,found,st.IsValid()); if st.IsValid(){fmt.Printf(" turretRot=%.3f hasRot=%v cooldown=%.3f targetID=%d targetBuild=%d",float32(st.FieldByName("TurretRotation").Float()),st.FieldByName("HasRotation").Bool(),float32(st.FieldByName("Cooldown").Float()),st.FieldByName("TargetID").Int(),st.FieldByName("TargetBuildPos").Int())}; fmt.Println()}}
func main(){reg:=protocol.NewContentRegistry(); ids,_:=vanilla.LoadContentIDs(filepath.Join("data","vanilla","content_ids.json")); vanilla.ApplyContentIDs(reg,ids); m,_:=worldstream.LoadWorldModelFromMSAV(filepath.Join("assets","worlds","file.msav"),reg); w:=world.New(world.Config{TPS:60}); w.SetModel(m); _=w.LoadVanillaProfiles(filepath.Join("data","vanilla","profiles.json")); inspectIndex(w,"initial index"); dump("initial direct", w.Model()); dump("initial clone", w.CloneModelForWorldStream()); w.Step(time.Second/60); inspectIndex(w,"after index"); dump("after direct", w.Model()); dump("after clone", w.CloneModelForWorldStream())}
